//! The shapes the Confluence import sends and accepts. TypeScript bindings are generated by `cargo test`.

use hub_core::Id;
use serde::{Deserialize, Serialize};
use ts_rs::TS;

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ConfluenceSettings {
    pub base_url: String,
    /// Set for Confluence Cloud (e-mail plus API token); empty for a personal access token.
    pub email: String,
    /// The end of the stored token; none when no token is stored. The token itself is never sent.
    pub token_hint: Option<String>,
    /// True when an address and a token are stored, so imports can run.
    pub configured: bool,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase", default)]
#[ts(export, optional_fields)]
pub struct ConfluenceSettingsUpdate {
    pub base_url: String,
    pub email: Option<String>,
    /// Blank or absent keeps the stored token.
    pub token: Option<String>,
    pub clear_token: Option<bool>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ConfluenceTestResult {
    pub ok: bool,
    pub message: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ConfluenceRemoteSpace {
    pub key: String,
    pub name: String,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, optional_fields)]
pub struct ConfluenceImportRequest {
    /// The key of the space in Confluence.
    pub space_key: String,
    /// Import only this page and what is under it.
    pub root_page_id: Option<String>,
    /// The key of the knowledge base space to write into; by default the Confluence key.
    pub target_space_key: Option<String>,
    /// Titles or ids of pages to leave out, together with everything under them.
    pub exclude: Option<Vec<String>>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ConfluenceFailure {
    pub title: String,
    pub reason: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ConfluenceGonePage {
    pub page_id: Id,
    pub title: String,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", default)]
#[ts(export)]
pub struct ConfluenceImportReport {
    pub wiki_space_key: String,
    pub created: i64,
    pub updated: i64,
    pub unchanged: i64,
    /// Pages left out: excluded ones with their subtrees, and pages detached here.
    pub skipped: i64,
    pub failed: Vec<ConfluenceFailure>,
    /// Mirrored pages that Confluence no longer has. They are left as they are.
    pub gone: Vec<ConfluenceGonePage>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ConfluenceImport {
    pub wiki_space_key: String,
    pub wiki_space_name: String,
    pub space_key: String,
    pub root_page_id: Option<String>,
    pub exclude: Vec<String>,
    /// The Confluence address the import last ran against.
    pub base_url: String,
    pub last_run_at: Option<String>,
    pub last_report: Option<ConfluenceImportReport>,
}
